// ═══ ResponseStatusException: throw inline with HTTP status ═══
@GetMapping("/{id}")
public Trade getTrade(@PathVariable String id) {
    return tradeService.findById(id)
        .orElseThrow(() -> new ResponseStatusException(
            HttpStatus.NOT_FOUND, "Trade not found: " + id));
    // No custom exception class needed! Status + message in one throw.
    // But: less structured than @ExceptionHandler (no custom ErrorResponse body).
}
