package com.bank.handler.service;

import com.bank.handler.exception.*;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.util.Map;

@Service
public class TradeService {

    private static final Map<String, String> TRADES = Map.of(
        "TRD-001", "RELIANCE", "TRD-002", "TCS");

    public String findById(String tradeId) {
        String symbol = TRADES.get(tradeId);
        if (symbol == null) throw new TradeNotFoundException(tradeId);
        return tradeId + ": " + symbol;
    }

    public String executeTrade(String symbol, BigDecimal amount) {
        if (symbol == null || symbol.isBlank()) throw new IllegalArgumentException("Symbol required");
        if (amount.compareTo(new BigDecimal("1000000")) > 0)
            throw new InsufficientBalanceException(new BigDecimal("500000"), amount);
        return "Executed: " + symbol + " Rs." + amount;
    }
}
