    private final TradeService tradeService;

    @GetMapping("/{id}")
    public String getTrade(@PathVariable String id) {
        return tradeService.findById(id);  // might throw TradeNotFoundException → 404
    }

    @PostMapping
    public String execute(@RequestParam String symbol, @RequestParam BigDecimal amount) {
        return tradeService.executeTrade(symbol, amount);
        // might throw IllegalArgumentException → 400
        // might throw InsufficientBalanceException → 400
    }
    // ZERO TRY-CATCH! Clean controller. Exceptions handled globally.
}
