package com.bank.handler;

import com.bank.handler.exception.*;
import com.bank.handler.service.TradeService;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import static org.assertj.core.api.Assertions.*;

class GlobalHandlerTest {

    TradeService service = new TradeService();

    @Test
    void notFound_throwsTradeNotFoundException() {
        assertThatThrownBy(() -> service.findById("TRD-999"))
            .isInstanceOf(TradeNotFoundException.class)
            .hasMessageContaining("not found");
        // GlobalExceptionHandler → 404 + {"error":"NOT_FOUND","message":"Trade not found: TRD-999"}
    }

    @Test
    void insufficientBalance_throwsException() {
        assertThatThrownBy(() -> service.executeTrade("RELIANCE", new BigDecimal("5000000")))
            .isInstanceOf(InsufficientBalanceException.class);
        // GlobalExceptionHandler → 400 + {"error":"INSUFFICIENT_BALANCE"}
    }

    @Test
    void invalidInput_throwsIllegalArgument() {
        assertThatThrownBy(() -> service.executeTrade("", new BigDecimal("1000")))
            .isInstanceOf(IllegalArgumentException.class);
        // GlobalExceptionHandler → 400 + {"error":"BAD_REQUEST"}
    }

    @Test
    void success_noException() {
        String result = service.findById("TRD-001");
        assertThat(result).contains("RELIANCE");
    }
}
